/** Read-only explanation of the audited engine, never executable customer configuration. */
export const RULE_CATALOG_VERSION = "ahlsell-product-rules-2026-09-27.6";
export const RULE_CATALOG_DATE = "27 september 2026";

export type RuleKind = "requirement" | "search" | "ranking" | "review" | "assumption" | "gap";
export const RULE_KIND_LABELS: Record<RuleKind, string> = {
  requirement: "Tekniskt krav", search: "Sökning & urval", ranking: "Poäng & ordning",
  review: "Manuell kontroll", assumption: "Fast antagande", gap: "Kontroll saknas"
};
export type RuleExample = { input: string; result: string };
export type MatchingRule = {
  id: string; title: string; when: string; result: string;
  kind?: RuleKind; notes?: string[]; example?: RuleExample;
  table?: { columns: string[]; rows: string[][] };
};
export type RuleGroup = {
  id: string; title: string; appliesTo: string; description: string;
  kind: RuleKind; sources: string[]; rules: MatchingRule[];
};
const rule = (id: string, title: string, when: string, result: string, extra: Partial<Omit<MatchingRule, "id" | "title" | "when" | "result">> = {}): MatchingRule => ({ id, title, when, result, ...extra });
const table = (columns: string[], rows: string[][]) => ({ columns, rows });

