export const MATCHING_RULES = MATCHING_RULE_GROUPS.flatMap(group => group.rules.map(item => ({
  ...item, kind: item.kind ?? group.kind, groupId: group.id, groupTitle: group.title,
  appliesTo: group.appliesTo, sources: group.sources
})));
export type CatalogRule = (typeof MATCHING_RULES)[number];

export function normalizeRuleSearch(value: string) {
  return value.toLocaleLowerCase("sv").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ø/g, "o").replace(/æ/g, "ae");
}
export function filterMatchingRules(query: string, kind: string = "all") {
  const words = normalizeRuleSearch(query.trim()).split(/\s+/).filter(Boolean);
  return MATCHING_RULES.filter(item => {
    if (kind !== "all" && item.kind !== kind) return false;
    const haystack = normalizeRuleSearch([item.title, item.id, item.groupTitle, item.appliesTo, item.when, item.result,
      ...(item.notes ?? []), ...(item.table?.rows.flat() ?? []), item.example?.input ?? "", item.example?.result ?? ""].join(" "));
    return words.every(word => haystack.includes(word));
  });
}

export function ruleSourceUrl(file: string) {
  return `https://github.com/MarcLars31/FlowX-Platform/blob/${RULE_CATALOG_VERSION}/apps/web/src/lib/${file}`;
}
